        west:{uv:[u,v+d,u+d,v+d+h]},
        north:{uv:[u+d,v+d,u+d+w,v+d+h]},
        east:{uv:[u+d+w,v+d,u+d+w+d,v+d+h]},
        south:{uv:[u+d+w+d,v+d,u+d+w+d+w,v+d+h]},
        up:{uv:[u+d,v,u+d+w,v+d]},
        down:{uv:[u+d+w,v,u+d+w+w,v+d]},
