                if (element >= 5) return soul ? 'soul_campfire_fire' : 'campfire_fire';
                if (campfireLit && ((element <= 3 && (face === 'up' || face === 'north'))
                    || (element === 4 && face === 'up'))) {
                    return soul ? 'soul_campfire_log_lit' : 'campfire_log_lit';
                }
