    function javaPottedPlantIdentifier(sourceBare) {
        const javaPlant = sourceBare.replace(/^potted_/, '');
        return `minecraft:${JAVA_POTTED_PLANT_ALIASES[javaPlant] || javaPlant}`;
    }

    function legacyJavaFlowerPotPlant(itemValue, dataValue) {
        const item = normalizeJavaIdentifier(itemValue || 'minecraft:air').replace(/^minecraft:/, '');
        const data = Math.trunc(Number(dataValue) || 0);
        if (item === 'air' || !item) return null;
        if (item === 'yellow_flower') return 'minecraft:dandelion';
        if (item === 'red_flower') {
            return `minecraft:${[
                'poppy', 'blue_orchid', 'allium', 'azure_bluet', 'red_tulip',
                'orange_tulip', 'white_tulip', 'pink_tulip', 'oxeye_daisy',
            ][data] || 'poppy'}`;
        }
        if (item === 'sapling') {
            return `minecraft:${['oak','spruce','birch','jungle','acacia','dark_oak'][data & 7] || 'oak'}_sapling`;
        }
        if (['cactus','brown_mushroom','red_mushroom','dead_bush'].includes(item)) return `minecraft:${item}`;
        return null;
    }

    function javaRotationToCardinalFacing(rotation) {
        const value = ((Math.trunc(Number(rotation) || 0) % 16) + 16) % 16;
        return ({0:'south',4:'west',8:'north',12:'east'})[value] || null;
    }

    function javaRotationToNearestCardinal(rotation) {
        const value = ((Math.trunc(Number(rotation) || 0) % 16) + 16) % 16;
        return ['south','west','north','east'][Math.round(value / 4) % 4];
    }

    const JAVA_HUGE_MUSHROOM_BLOCKS = new Set(['red_mushroom_block', 'brown_mushroom_block', 'mushroom_stem']);
    const JAVA_MUSHROOM_SIGNATURES = Object.freeze({
        0: 0,
        37: 1,
        5: 2,
        21: 3,
        33: 4,
        1: 5,
        17: 6,
        41: 7,
        9: 8,
        25: 9,
        60: 10,
    });

    function javaHugeMushroomBits(sourceBare, properties) {
        const faceBits = {up:1, down:2, north:4, south:8, east:16, west:32};
        let signature = 0;
        for (const [face, bit] of Object.entries(faceBits)) {
            const value = properties?.[face];
            if (value === true || value === 'true' || value === 1 || value === '1') signature |= bit;
        }
        if (signature === 63) return {bits: sourceBare === 'mushroom_stem' ? 15 : 14, exact: true, signature};
        if (Object.prototype.hasOwnProperty.call(JAVA_MUSHROOM_SIGNATURES, signature)) {
            return {bits: JAVA_MUSHROOM_SIGNATURES[signature], exact: true, signature};
        }
        const candidates = Object.entries(JAVA_MUSHROOM_SIGNATURES).map(([candidateSignature, bits]) => ({
            signature: Number(candidateSignature),
            bits,
        }));
        candidates.push({signature: 63, bits: sourceBare === 'mushroom_stem' ? 15 : 14});
        const mismatchCount = candidate => {
            let value = signature ^ candidate.signature;
            let count = 0;
            while (value) { count += value & 1; value >>>= 1; }
            return count;
        };
        candidates.sort((a, b) => mismatchCount(a) - mismatchCount(b) || a.bits - b.bits);
        return {bits: candidates[0].bits, exact: false, signature};
    }

