        stripe_downright:'drs', stripe_downleft:'dls', small_stripes:'ss', straight_cross:'cr', cross:'sc', diagonal_left:'ld',
        diagonal_up_right:'rud', diagonal_up_left:'lud', diagonal_right:'rd', half_vertical:'vh', half_vertical_right:'vhr',
        half_horizontal:'hh', half_horizontal_bottom:'hhb', square_bottom_left:'bl', square_bottom_right:'br', square_top_left:'tl',
        square_top_right:'tr', triangle_bottom:'bt', triangle_top:'tt', triangles_bottom:'bts', triangles_top:'tts', circle:'mc',
        rhombus:'mr', border:'bo', curly_border:'cbo', gradient:'gra', gradient_up:'gru', bricks:'bri', creeper:'cre', skull:'sku',
