        const readRange=()=>{const result=form.getResult(); const from=result.from.map(v=>Math.round(Number(v)||0));const size=result.size.map(v=>Math.max(1,Math.round(Number(v)||1))); if(result.shape==='circle')size[1]=1;if(result.mode==='scatter'&&result.on_surface&&result.surface_action!=='paint')size[1]+=1;return {from,size,to:from.map((v,i)=>v+size[i]-1),volume:size.reduce((a,b)=>a*b,1),settings:{shape:result.shape,mode:result.mode,density:result.density,seed:result.seed,onlyEmpty:result.only_empty&&result.surface_action!=='paint',surfaceBlocks:result.surface_filter==='soil'?['minecraft:grass_block','minecraft:dirt','minecraft:coarse_dirt','minecraft:podzol','minecraft:moss_block','minecraft:dirt_with_roots']:[],surfacePaint:result.surface_action==='paint',onSurface:result.mode==='scatter'&&result.on_surface,palette:result.mix?structureHotbarSlots:[]}};};
        session.focus=()=>{const range=readRange();return frameStructureView(false,{minimum:range.from,maximum:range.to});};
        focus.onclick=session.focus;
        const syncPin=()=>{pin.classList.toggle('selected',session.keepOpen);pin.setAttribute('aria-pressed',String(session.keepOpen));};
        pin.onclick=()=>{session.keepOpen=!session.keepOpen;writeStudioPreferences({fillKeepOpen:session.keepOpen});syncPin();};syncPin();
        let previousShape=null;
        const preview=()=>{
            const range=readRange(),shape=range.settings.shape;
            if(previousShape!==shape){
                previousShape=shape;ghost.geometry.dispose();wire.geometry.dispose();
                ghost.geometry=shape==='ellipsoid'?new THREE.SphereGeometry(.5,20,12):shape==='cylinder'||shape==='circle'?new THREE.CylinderGeometry(.5,.5,1,32):new THREE.BoxGeometry(1,1,1);
                wire.geometry=new THREE.EdgesGeometry(ghost.geometry);
            }
            ghost.position.fromArray(range.from.map((v,i)=>(v+range.size[i]/2)*BLOCK_SIZE));ghost.scale.fromArray(range.size.map(v=>v*BLOCK_SIZE));wire.position.copy(ghost.position);wire.scale.copy(ghost.scale);
            const sampleVolume=Math.min(range.volume,4096);let included=0;const vertices=[];
            const bounds={minimum:range.from,size:range.size};
            for(let i=0;i<sampleVolume;i++){const n=Math.floor(i*range.volume/sampleVolume);const cell=[range.from[0]+Math.floor(n/(range.size[1]*range.size[2])),range.from[1]+Math.floor(n/range.size[2])%range.size[1],range.from[2]+n%range.size[2]];if(terrainShapeContains(cell,bounds,range.settings)){const current=ensureLogicalRuntime()?.byKey.get(spatialRecordKey(...cell,brush.layer));const below=ensureLogicalRuntime()?.byKey.get(spatialRecordKey(cell[0],cell[1]-1,cell[2],brush.layer));if(range.settings.onSurface){const support=range.settings.surfacePaint?current:below;if(range.settings.surfaceBlocks?.length&&!range.settings.surfaceBlocks.includes(support?.mcstructure_block))continue;if(range.settings.surfacePaint){const above=ensureLogicalRuntime()?.byKey.get(spatialRecordKey(cell[0],cell[1]+1,cell[2],brush.layer));if(!current||current.mcstructure_block==='minecraft:air'||above&&above.mcstructure_block!=='minecraft:air')continue;}else if(!below||below.mcstructure_block==='minecraft:air'||current&&current.mcstructure_block!=='minecraft:air')continue;}included++;vertices.push(...cell.map(v=>(v+.5)*BLOCK_SIZE));}}
            points.geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
            if(vertices.length)points.geometry.computeBoundingSphere();else points.geometry.boundingSphere=new THREE.Sphere(new THREE.Vector3(),0);
            points.visible=shape==='terrain'||range.settings.mode==='scatter';ghost.visible=!points.visible;
            const estimate=Math.round(included*range.volume/sampleVolume);
            count.textContent=`${range.volume>4096?'≈ ':''}${estimate.toLocaleString()} · ${range.size.join(' × ')}`;
            apply.disabled=session.busy||range.volume>MAX_STRUCTURE_VOLUME;session.layout();
        };
        form.on('change',({result,changed_keys})=>{if(result.block&&result.block!==brush.block)brush=normalizeStructureBrushDescriptor({...brush,block:result.block});preview();}); preview(); window.addEventListener('resize',session.layout);Blockbench.on('select_project',session.close);
        let drag=null;
        title.style.cursor='grab';title.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;session.dragged=true;drag={x:event.clientX,y:event.clientY,left:root.offsetLeft,top:root.offsetTop};title.setPointerCapture?.(event.pointerId);event.preventDefault();});
        title.addEventListener('pointermove',event=>{if(!drag)return;root.style.left=`${Math.min(innerWidth-root.offsetWidth,Math.max(0,drag.left+event.clientX-drag.x))}px`;root.style.top=`${Math.min(innerHeight-root.offsetHeight,Math.max(0,drag.top+event.clientY-drag.y))}px`;});
        title.addEventListener('pointerup',()=>drag=null);title.addEventListener('pointercancel',()=>drag=null);
        session.apply=apply.onclick=()=>{
            if (Project!==project) return closeTerrainFill();
            if(session.busy)return;
            const range=readRange();
            const commit=async()=>{session.busy=true;apply.disabled=true;if(!session.keepOpen)closeTerrainFill();try {const filled=await fillLogicalRegionProgressive(range.from,range.to,brush.block,JSON.parse(brush.statesJson||'{}'),brush.version,brush.layer,{terrainShape:range.settings});Blockbench.showQuickMessage(trf('bedrock_structure.message.filled_cells','Filled {0} cells.',[filled.toLocaleString()]),2200);}catch(error){showError('fill region',error);throw error;}finally{session.busy=false;if(terrainFillSession===session)preview();}};
            if (range.volume>=LOGICAL_FILL_WARNING_THRESHOLD) Blockbench.showMessageBox({title:tr('bedrock_structure.dialog.fill','Fill region'),message:`${range.volume.toLocaleString()} blocks · ${range.size.join(' × ')}`,buttons:['dialog.continue','dialog.cancel'],confirm:0,cancel:1},button=>{if(button===0)commit();});
            else return commit();
        };
        session.configure=settings=>{
            if(settings.brush){brush=normalizeStructureBrushDescriptor(settings.brush);updateBlockButton();}
            const values={};for(const key of Object.keys(form.form_data))if(settings[key]!==undefined)values[key]=settings[key];
            form.setValues(values);form.update();preview();
        };
        session.configure(initial);
