        structurePackLibrary=createLightflowPackLibrary({fs,path,root,Zip:typeof JSZip!=='undefined'?JSZip:null,hash:value=>crypto.createHash('sha256').update(value).digest('hex'),fetchBytes,fetchRange,parseJson:content=>typeof autoParseJSON==='function'?autoParseJSON(content,false):JSON.parse(content)});
