        if(!ids.length){const resolver=resourcePackResolvers.get(project);resourcePackResolvers.delete(project);project.mcstructure_resource_pack_path='';project.mcstructure_resource_pack_stack_json='[]';shapeCache.clear();try{buildOptimizedPreview();}finally{resolver?.dispose?.();}project.saved=false;syncStructurePanel();for(const key of ['export_path','save_path','import_path'])rememberStructurePackProject(project,project[key]);notifyStructurePackResources(project);return true;}
