    function installStructureToolbarItems() {
        const toolbars = typeof Toolbars !== 'undefined' ? Toolbars : null;
        if (!toolbars) return;

        const addOnce = (toolbar, item, position) => {
            if (!toolbar || !item || !Array.isArray(toolbar.children) || toolbar.children.includes(item)) return;
            toolbar.add(item, position);
            structureToolbarItems.push({toolbar, item});
        };

        [structureSelectTool, structurePlaceTool, structureEraseTool, structurePickTool]
            .filter(Boolean)
            .forEach((tool, index) => addOnce(toolbars.tools, tool, index));

        const mainToolbar = toolbars.main_tools;
        if (!mainToolbar) return;
        const actionIds = [
            'bedrock_structure_frame',
            'bedrock_structure_inventory',
            'bedrock_structure_fill_region',
            'bedrock_structure_replace_blocks',
            'bedrock_structure_copy_cells',
            'bedrock_structure_paste_cells',
            'bedrock_structure_move_selection',
            'bedrock_structure_transform_selection',
            'bedrock_structure_duplicate_selection',
            'bedrock_structure_delete_selection',
            'bedrock_structure_toggle_secondary',
        ];
        // Terrain operations already live in the terrain rail and selection
        // context. Keep native editing options free of a second command strip.
        for (const id of actionIds) {
            const item = BarItems[id] || structureActionItems.get(id);
            if (item) window.LightManagerUI?.removeToolbarAction?.(item, ['main_tools']);
        }
    }

    function removeStructureToolbarItems() {
        const affectedToolbars = new Set();
        for (const entry of structureToolbarItems.splice(0).reverse()) {
            try {
                entry.toolbar?.remove?.(entry.item, false);
                affectedToolbars.add(entry.toolbar);
            } catch (error) {
                warnOnce('remove structure toolbar item', error);
            }
        }
        for (const toolbar of affectedToolbars) toolbar.update?.(true)?.save?.();
        structureActionItems.clear();
    }

